const fs = require('fs');
const path = require('path');

const LANGUAGES = ['es', 'en'];

function deepMerge(obj1, obj2) {
  const result = { ...obj1 };

  for (const key in obj2) {
    if (obj2[key] && typeof obj2[key] === 'object' && !Array.isArray(obj2[key])) {
      result[key] = deepMerge(result[key] || {}, obj2[key]);
    } else {
      result[key] = obj2[key];
    }
  }

  return result;
}

function mergeLanguageFiles(lang) {
  const baseDir = path.join(__dirname, '../public/locales', lang);

  // Cargar archivos existentes
  const files = [
    'translation.json',
    'pages.json',
    'tours.json',
    'pages-content.json'
  ];

  let merged = {};

  for (const file of files) {
    const filePath = path.join(baseDir, file);
    if (fs.existsSync(filePath)) {
      try {
        const content = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
        merged = deepMerge(merged, content);
        console.log(`Cargado: ${file}`);
      } catch (e) {
        console.warn(`Error cargando ${file}: ${e.message}`);
      }
    }
  }

  // Guardar archivo unificado
  const outputPath = path.join(baseDir, 'translation-full.json');
  fs.writeFileSync(outputPath, JSON.stringify(merged, null, 2));
  console.log(`Guardado: translation-full.json (${Object.keys(merged).length} claves)`);

  return merged;
}

// Ejecutar para cada idioma
for (const lang of LANGUAGES) {
  console.log(`\nProcesando idioma: ${lang}`);
  mergeLanguageFiles(lang);
}

console.log('\nUnificación completada');
